def switch_on_enum_with_a_single_case(
    kind: aas_types.Kind
) -> bool:
    """Check the switch with a single case and no default."""
    # pylint: disable=all
    if kind == aas_types.Kind.DELTA:
        return False
    return True


def switch_on_enum_with_default(
    kind: aas_types.Kind
) -> bool:
    """Check the switch with a case per form of labels and a default."""
    # pylint: disable=all
    if kind == aas_types.Kind.ALPHA:
        return True
    elif kind in (aas_types.Kind.BETA, aas_types.Kind.GAMMA):
        return False
    else:
        return True


def switch_on_enum_with_labels_in_tuple(
    kind: aas_types.Kind
) -> bool:
    """Check the switch with the labels given as a tuple."""
    # pylint: disable=all
    if kind in (aas_types.Kind.ALPHA, aas_types.Kind.BETA, aas_types.Kind.GAMMA):
        return True
    else:
        return False


def switch_on_enum_with_pass(
    kind: aas_types.Kind
) -> bool:
    """
    Check the switch with the branches which pass and complete normally.
    """
    # pylint: disable=all
    result = True
    if kind in (aas_types.Kind.ALPHA, aas_types.Kind.BETA):
        pass
    elif kind == aas_types.Kind.GAMMA:
        result = False
    else:
        pass
    return result


def switch_on_enum_with_variables_in_cases(
    kind: aas_types.Kind,
    text: str
) -> bool:
    """Check the variables defined in the cases of the switch."""
    # pylint: disable=all
    if kind == aas_types.Kind.ALPHA:
        length = len(text)
        return length > 1
    elif kind == aas_types.Kind.BETA:
        length = len(text)
        return length > 2
    else:
        return True


def switch_on_str(
    text: str
) -> bool:
    """Check the switch on a string."""
    # pylint: disable=all
    if text == 'alpha':
        return True
    elif text in ('beta', 'gamma'):
        return False
    elif text in ('delta', 'epsilon'):
        return False
    else:
        return len(text) > 0


def switch_on_constrained_str(
    text: str
) -> bool:
    """Check the switch on a constrained primitive."""
    # pylint: disable=all
    if text in ('forbidden', 'banned'):
        return False
    else:
        return True


def switch_on_int(
    number: int
) -> bool:
    """Check the switch on an integer."""
    # pylint: disable=all
    if number == -1:
        return False
    elif number in (0, 1):
        return True
    elif number in (2, 3):
        return False
    else:
        return number > 3


def nested_switches(
    kind: aas_types.Kind,
    number: int
) -> bool:
    """
    Check the nested switches, including an ``elif`` on another subject.
    """
    # pylint: disable=all
    if kind == aas_types.Kind.ALPHA:
        if number == 0:
            return True
        else:
            return number > 10
    elif kind == aas_types.Kind.BETA:
        if number == 1:
            return False
    else:
        if number == 2:
            return False
    return True


class _Transformer(
        aas_types.AbstractTransformer[
            Iterator[Error]
        ]
):
    # noinspection PyMethodMayBeStatic
    def transform_something(
            self,
            that: aas_types.Something
    ) -> Iterator[Error]:
        if not nested_switches(that.kind, that.number):
            yield Error(
                'Kind and number must be consistent'
            )

        if not switch_on_int(that.number):
            yield Error(
                'Number must be acceptable'
            )

        if not switch_on_constrained_str(that.name):
            yield Error(
                'Name must not be forbidden'
            )

        if not switch_on_str(that.text):
            yield Error(
                'Text must be acceptable'
            )

        if not (
            switch_on_enum_with_variables_in_cases(
                that.kind,
                that.text
            )
        ):
            yield Error(
                'Text must be long enough for the kind'
            )

        if not switch_on_enum_with_pass(that.kind):
            yield Error(
                'Kind must not be gamma'
            )

        if not switch_on_enum_with_labels_in_tuple(that.kind):
            yield Error(
                'Kind must be alpha, beta or gamma'
            )

        if not switch_on_enum_with_default(that.kind):
            yield Error(
                'Kind must be neither beta nor gamma'
            )

        if not switch_on_enum_with_a_single_case(that.kind):
            yield Error(
                'Kind must not be delta'
            )

        for error in verify_non_empty_string(that.name):
            error.path._prepend(
                PropertySegment(
                    that,
                    'name'
                )
            )
            yield error


_TRANSFORMER = _Transformer()


def verify(
        that: aas_types.Class
) -> Iterator[Error]:
    """
    Verify the constraints of :paramref:`that` recursively.

    :param that: instance whose constraints we want to verify
    :yield: constraint violations
    """
    yield from _TRANSFORMER.transform(that)


def verify_non_empty_string(
        that: str
) -> Iterator[Error]:
    """Verify the constraints of :paramref:`that`."""
    if not (len(that) > 0):
        yield Error(
            'At least one character'
        )


